{
  "technical_and_design_decisions": [
    "U1: Add new 'undeployed' enum value to Mesos AppStatus and ensure correct translation from Marathon/Chronos task states; follow existing SPI status mapping conventions.",
    "U2: Implement a new REST controller endpoint (e.g., POST /bindings/clean) that delegates to the existing RabbitBindingCleaner component; reuse the existing admin/security model of the REST API.",
    "U3: Optimize YARN deployer by introducing parallel application submission, caching of the YarnClient, and reuse of the application-id resolution path to reduce per-module deployment latency.",
    "U4: Upgrade Spring Hadoop (SHDP) to 2.2.1.GA which includes backported fixes; move Spring and Hadoop dependency versions to more recent compatible releases while keeping backward compatibility for users on HDP/CDH.",
    "U5: Upgrade Spring Integration to 4.2.2.GA; align dependent module versions and adjust any deprecated API usages.",
    "U6: Modify the Kafka bus binder to allow configuring a partitioning key even when a single downstream module is bound, by passing the partition key through the producer configuration rather than relying on module count.",
    "U7: Upgrade Spring Boot and Spring Cloud Build BOM to their latest revisions; resolve any resulting transitive dependency conflicts.",
    "U8: Add a 'Limitations' section to the composed-jobs reference documentation describing HSQLDB-specific constraints (e.g., lack of certain SQL features, in-memory state loss on restart)."
  ],
  "assumptions": [
    "A single developer familiar with Spring Cloud Data Flow / Spring XD codebase performs all the work.",
    "Each user story is implemented with associated unit tests; the effort figures include coding plus per-story unit testing.",
    "For U3 (YARN deployer optimization), the scope is limited to parallelization and caching inside the deployer; a full benchmarking/performance-tuning cycle is not included.",
    "Version upgrade work (U4, U5, U7) assumes the dependency graph is already close to the target version, so effort is mainly bumping versions, fixing compile errors, and re-running the test suite.",
    "The Kafka partitioning change (U6) is API/configuration-only and does not require changes to Kafka client internals or message routing logic.",
    "Documentation updates (U8) target the project's existing reference docs (Asciidoctor) and do not require new tooling.",
    "No production incident handling, stakeholder meetings, or unrelated bug fixes are included.",
    "A final end-to-end integration test pass is included once to validate that all changes work together."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Environment setup and codebase familiarization",
      "activity_description": "Check out the project, build it locally, run the existing test suite, and confirm the development environment (JDK 17+, build tool, IDE) is ready."
    },
    {
      "activity_id": "A2",
      "activity_name": "Requirements analysis and design notes",
      "activity_description": "Review each user story, locate the relevant source files in the SPI, deployer, binder, and documentation modules, and document the design approach for each change."
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Mesos SPI 'undeployed' status",
      "activity_description": "Add the new 'undeployed' value to the Mesos status enum, map Marathon/Chronos task states that correspond to an undeployed application, and add unit tests covering the new mapping."
    },
    {
      "activity_id": "A4",
      "activity_name": "U2 - Rabbit binder broker cleaner REST endpoint",
      "activity_description": "Expose a new REST endpoint that invokes the existing RabbitBindingCleaner, wire it into the controller hierarchy, add input validation, and add unit/integration tests."
    },
    {
      "activity_id": "A5",
      "activity_name": "U3 - YARN deployer optimization",
      "activity_description": "Refactor the YARN deployer to submit stream modules and definition components in parallel, cache the YarnClient across deployments, and add a basic timing/logging test to confirm the optimization is effective."
    },
    {
      "activity_id": "A6",
      "activity_name": "U4 - Upgrade to SHDP 2.2.1.GA",
      "activity_description": "Bump Spring Hadoop to 2.2.1.GA, align Spring and Hadoop transitive versions, fix any compile or API breakage, and run the affected module tests."
    },
    {
      "activity_id": "A7",
      "activity_name": "U5 - Upgrade to Spring Integration 4.2.2.GA",
      "activity_description": "Bump Spring Integration to 4.2.2.GA, resolve dependency conflicts, adjust any deprecated API usages, and re-run module tests."
    },
    {
      "activity_id": "A8",
      "activity_name": "U6 - Kafka single-module partitioning key",
      "activity_description": "Update the Kafka bus binder so that a partition key can be configured/applied even when only one downstream module is bound, including property parsing and unit tests."
    },
    {
      "activity_id": "A9",
      "activity_name": "U7 - Upgrade Boot and Spring Cloud Build revisions",
      "activity_description": "Bump Spring Boot and the Spring Cloud Build BOM to the latest revisions, resolve transitive dependency conflicts, and run impacted tests."
    },
    {
      "activity_id": "A10",
      "activity_name": "U8 - HSQLDB composed-jobs documentation",
      "activity_description": "Research the HSQLDB-specific limitations that affect composed jobs (e.g., lack of certain SQL features, persistence behavior) and add a 'Limitations' section to the composed-jobs reference documentation."
    },
    {
      "activity_id": "A11",
      "activity_name": "End-to-end integration testing",
      "activity_description": "Run the full integration test suite across all modified modules to confirm the upgrades, new SPI status, REST endpoint, deployer optimization, and Kafka change work together."
    },
    {
      "activity_id": "A12",
      "activity_name": "Bug fixing, code review, and final polish",
      "activity_description": "Address issues found during integration tests, perform a self code review, apply minor refactors, and prepare the changes for commit."
    }
  ],
  "reported_total": {
    "most_likely_effort": 82
  }
}
